// 独立新邀请三源的严格typed/JSON形状；目录未启用时无任何旧Interaction/预约字段变化。
#include "resident/checkpoint/checkpoint_decode_lifecycle.hpp"
#include "visit_appointment_state.hpp"
#include "resident/domains/interaction/s3_leaf_life_codec.hpp"
#include "resident/domains/tasks/task_dynamic_codec.hpp"
#include "resident/domains/tasks/task_dynamic_projection.hpp"
#include "resident/domains/interaction/interaction_source_projection.hpp"
#include <set>
namespace hanmo::resident {namespace {
template<class A>Status contact(A& a,VisitMessageContact& v){a.field("actor_id",v.actor_id);a.field("custodian_actor_id",v.custodian_actor_id);a.field("place_id",v.place_id);a.field("role_id",v.role_id);a.field("session_id",v.session_id);a.field("dialogue_id",v.dialogue_id);a.field("node_id",v.node_id);return a.field("tick",v.tick);}
template<class A>Status receipt(A& a,VisitAppointmentPlayerReceipt& v){a.field("result_id",v.result_id);a.field("request_actor_id",v.request_actor_id);a.field("request_sequence",v.request_sequence);return a.field("result_revision",v.result_revision);}
template<class A>Status authored(A& a,VisitAppointmentAuthoredOrigin& v){a.field("intent_id",v.intent_id);return a.field("reception_claim_fact_id",v.reception_claim_fact_id);}
template<class A>Status terms(A& a,VisitAppointmentTerms& v){a.field("appointment_policy_id",v.appointment_policy_id);a.field("inviter_actor_id",v.inviter_actor_id);a.field("invitee_actor_id",v.invitee_actor_id);a.field("place_id",v.place_id);a.field("role_id",v.role_id);a.field("offered_tick",v.offered_tick);a.field("accept_before_tick",v.accept_before_tick);a.field("earliest_tick",v.earliest_tick);a.field("latest_tick",v.latest_tick);return a.field("duration_ticks",v.duration_ticks);}
template<class A>Status offered(A& a,VisitAppointmentOffered& v){a.field("fact_id",v.fact_id);a.field("policy_id",v.policy_id);a.field("message_fact_id",v.message_fact_id);a.field("received_fact_id",v.received_fact_id);a.object("contact",[&](auto& c){return contact(c,v.contact);});a.object("terms",[&](auto& c){return terms(c,v.terms);});a.optional("player_receipt",v.player_receipt,[](auto& c,auto& r){return receipt(c,r);});return a.optional("authored_origin",v.authored_origin,[](auto& c,auto& r){return authored(c,r);});}
template<class A>Status collected(A& a,VisitAppointmentCollected& v){a.field("fact_id",v.fact_id);a.field("invitation_fact_id",v.invitation_fact_id);a.object("contact",[&](auto& c){return contact(c,v.contact);});return a.optional("player_receipt",v.player_receipt,[](auto& c,auto& r){return receipt(c,r);});}
template<class A>Status accepted(A& a,VisitAppointmentAccepted& v){a.field("fact_id",v.fact_id);a.field("invitation_fact_id",v.invitation_fact_id);a.field("collection_fact_id",v.collection_fact_id);a.field("actor_id",v.actor_id);a.field("tick",v.tick);return a.optional("player_receipt",v.player_receipt,[](auto& c,auto& r){return receipt(c,r);});}
template<class A>Status state(A& a,VisitAppointmentState& v){a.field("version",v.version);if(v.version!=1&&v.version!=2)return a.reject("UnsupportedVisitAppointmentVersion");auto s=dynamic_codec::table(a,"offered",v.offered,[](auto& c,auto& r){return offered(c,r);});if(!s.ok)return s;s=dynamic_codec::table(a,"collected",v.collected,[](auto& c,auto& r){return collected(c,r);});if(!s.ok)return s;s=dynamic_codec::table(a,"accepted",v.accepted,[](auto& c,auto& r){return accepted(c,r);});if(!s.ok)return s;if(v.version==1)return v.life_sources.empty()?a.status():a.reject("UnselectedVisitAppointmentLifeSources");return dynamic_codec::table(a,"life_sources",v.life_sources,[](auto&c,auto&r){c.object("death_ref",[&](auto&d){return s3_leaf_life_codec::death(d,r.death_ref);});c.field("invitation_fact_id",r.invitation_fact_id);dynamic_codec::enumeration(c,"role",r.role,1);return c.object("effect",[&](auto&d){return s3_leaf_life_codec::fields(d,r.effect,2);});});}
Status unique(const BoundaryValue& v,std::size_t depth=0){if(depth>CodecVisitor::max_depth)return common_failure("VisitAppointmentTooDeep");if(const auto* d=v.as<BoundaryValue::Dict>()){if(d->size()>CodecVisitor::max_items)return common_failure("VisitAppointmentTooLarge");std::set<StableId> keys;for(const auto& f:*d){if(!keys.insert(f.first).second)return common_failure("DuplicateVisitAppointmentField",f.first);auto r=unique(f.second,depth+1);if(!r.ok)return r;}}if(const auto* rows=v.as<BoundaryValue::Array>()){if(rows->size()>CodecVisitor::max_items)return common_failure("VisitAppointmentTooLarge");for(const auto& row:*rows){auto r=unique(row,depth+1);if(!r.ok)return r;}}return common_success();}
}
Status visit_visit_appointments_checkpoint(CodecVisitor& c,VisitAppointmentState& s){return state(c,s);}
Status emit_visit_appointments_fields(ProjectionWriter&w,const VisitAppointmentState&v){dynamic_projection::Archive a(w);return state(a,const_cast<VisitAppointmentState&>(v));}
BoundaryValue encode_visit_appointments(const VisitAppointmentState& s){BoundaryValue value;BoundaryProjectionWriter writer(value);auto checked=writer.object("",[&](auto& out){return emit_visit_appointments_fields(out,s);});if(checked.ok)checked=writer.finish();if(!checked.ok){boundary::DecodeFailure failure(checked.error.original.code,checked.error.original.path);failure.error=checked.error;throw failure;}return value;}
Outcome<VisitAppointmentState> decode_visit_appointments(const BoundaryValue& v){auto r=unique(v);if(!r.ok)return {false,{},r.error};VisitAppointmentState s;dynamic_codec::JsonArchive a(v);r=state(a,s);if(r.ok)r=a.finish();return r.ok?Outcome<VisitAppointmentState>{true,std::move(s),{}}:Outcome<VisitAppointmentState>{false,{},r.error};}
Status emit_visit_appointment_fact_fields(ProjectionWriter&w,const VisitAppointmentState&s,const StableId&id,const FactRecord*expected){dynamic_projection::Archive a(w);Status valid;StableId kind;const StableId*actual_id=nullptr;if(const auto*row=s.offered.find(id)){valid=offered(a,const_cast<VisitAppointmentOffered&>(*row));kind=visit_appointment_offered_kind;actual_id=&row->fact_id;}else if(const auto*row=s.collected.find(id)){valid=collected(a,const_cast<VisitAppointmentCollected&>(*row));kind=visit_appointment_collected_kind;actual_id=&row->fact_id;}else if(const auto*row=s.accepted.find(id)){valid=accepted(a,const_cast<VisitAppointmentAccepted&>(*row));kind=visit_appointment_accepted_kind;actual_id=&row->fact_id;}else return common_failure("UnknownVisitAppointmentFact",id);if(!valid.ok)return valid;if(expected&&(!actual_id||*actual_id!=id||kind!=expected->kind))return common_failure("VisitAppointmentFactMismatch",id);w.field("kind",kind);w.text("domain",std::string_view(visit_appointment_module));return w.status();}
Outcome<BoundaryValue> encode_visit_appointment_fact(const VisitAppointmentState& s,const StableId& id){BoundaryValue value;BoundaryProjectionWriter writer(value);auto checked=writer.object("",[&](auto& out){return emit_visit_appointment_fact_fields(out,s,id);});if(checked.ok)checked=writer.finish();return checked.ok?Outcome<BoundaryValue>{true,std::move(value),{}}:Outcome<BoundaryValue>{false,{},checked.error};}
}
